#include<stdio.h>

int comp=0;

void maxmin(int a[],int low,int high,int *max,int *min)
{
if(low==high)
{
*max=a[low];
*min=a[low];
}
else if(high==low+1)
{
comp++;
if(a[low]>a[high])
{
*max=a[low];
*min=a[high];
}
else
{
*max=a[high];
*min=a[low];
}
}
else
{
int mid=(low+high)/2;
int max1,min1,max2,min2;

maxmin(a,low,mid,&max1,&min1);
maxmin(a,mid+1,high,&max2,&min2);

comp++;
if(max1>max2)
*max=max1;
else
*max=max2;

comp++;
if(min1<min2)
*min=min1;
else
*min=min2;
}
}

int main()
{
int n;
scanf("%d",&n);

int a[n];

for(int i=0;i<n;i++)
scanf("%d",&a[i]);

int max,min;

maxmin(a,0,n-1,&max,&min);

printf("Max: %d\n",max);
printf("Min: %d\n",min);
printf("Comparisons: %d",comp);

return 0;
}

#include <stdio.h>

int comparisons=0;
int merges=0;

void merge(int arr[],int l,int m,int r)
{
int i,j,k;
int n1=m-l+1;
int n2=r-m;

int L[n1],R[n2];

for(i=0;i<n1;i++)
L[i]=arr[l+i];

for(j=0;j<n2;j++)
R[j]=arr[m+1+j];

i=0;
j=0;
k=l;

merges++;

while(i<n1 && j<n2)
{
comparisons++;

if(L[i]<=R[j])
{
arr[k]=L[i];
i++;
}
else
{
arr[k]=R[j];
j++;
}
k++;
}

while(i<n1)
{
arr[k]=L[i];
i++;
k++;
}

while(j<n2)
{
arr[k]=R[j];
j++;
k++;
}
}

void mergeSort(int arr[],int l,int r)
{
if(l<r)
{
int m=(l+r)/2;

mergeSort(arr,l,m);
mergeSort(arr,m+1,r);
merge(arr,l,m,r);
}
}

int main()
{
int n;
scanf("%d",&n);

int arr[n];

for(int i=0;i<n;i++)
scanf("%d",&arr[i]);

mergeSort(arr,0,n-1);

printf("Sorted array: ");
for(int i=0;i<n;i++)
printf("%d ",arr[i]);

printf("\nComparisons: %d",comparisons);
printf("\nMerges: %d",merges);

return 0;
}

