def histogram(l):
    freq = {}
    for num in l:
        freq[num] = freq.get(num, 0) + 1
    result = [(num, count) for num, count in freq.items()]
    result.sort(key=lambda x: (x[1], x[0]))
    return result


def transcript(coursedetails, studentdetails, grades):
    # Make lookup dictionaries
    course_dict = dict(coursedetails)
    student_dict = dict(studentdetails)

    # Collect grades per student
    student_grades = {}
    for roll, course, grade in grades:
        if roll not in student_grades:
            student_grades[roll] = []
        student_grades[roll].append((course, course_dict[course], grade))

    # Sort each student's courses by coursecode
    for roll in student_grades:
        student_grades[roll].sort(key=lambda x: x[0])

    # Build final list sorted by rollnumber
    result = []
    for roll in sorted(student_grades.keys()):
        result.append((roll, student_dict[roll], student_grades[roll]))

    return result

